import { ArrowRight, BriefcaseBusiness, MapPin } from 'lucide-react'; import SectionTitle from '../components/SectionTitle';
const roles=[['Healthcare','International opportunities for qualified professionals.'],['Construction','Roles for skilled site and technical talent.'],['Hospitality','Service and guest-experience career pathways.'],['Information Technology','Growing roles for digital and technical professionals.'],['Engineering','Opportunities for specialist engineering talent.'],['Skilled Trades','Practical career pathways for experienced tradespeople.']];
export default function Jobs({page,navigate}){const candidate=page==='candidates';return <><section className="page-hero"><div className="container"><p className="eyebrow light">{candidate?'For candidates':'Global opportunities'}</p><h1>{candidate?'Your skills can take you':'Explore your next\ncareer move.'}</h1><p>{candidate?'Share your profile and let’s discuss the opportunity that fits your ambitions.':'Browse the fields we support. Specific openings will be published as they become available.'}</p></div></section><section className="section surface"><div className="container"><SectionTitle eyebrow="Explore fields" title="Career pathways with global potential" text="No opportunities are currently listed. Please check back soon or contact our team to discuss your profile."/><div className="row g-4">{roles.map(([t,x])=><div className="col-12 col-md-6 col-lg-4" key={t}><article className="job-card"><div><BriefcaseBusiness/><span>Opportunity area</span></div><h3>{t}</h3><p>{x}</p><div className="job-meta"><MapPin/> International</div><button className="text-link" onClick={()=>navigate('contact')}>Register your interest <ArrowRight/></button></article></div>)}</div></div></section></>}
